// Build internal link candidates from published posts
const publishedPosts = $input.all().map(item => item.json);
const linkCandidates = publishedPosts
  .filter(p => p.live_url && p.suggested_title)
  .map(p => `- [${p.suggested_title}](${p.live_url})`)
  .join('\n');

const currentRow = $('Read Next Ready Row').first().json;
const publishDate = new Date().toISOString().split('T')[0];

return [{
  json: {
    ...currentRow,
    internalLinkCandidates: linkCandidates || 'none yet',
    publishDate
  }
}];

// Validate the AI output has proper frontmatter
const content = $input.first().json.message?.content || $input.first().json.text || '';

// Check it starts with frontmatter
if (!content.trim().startsWith('---')) {
  throw new Error('AI output does not start with frontmatter (---)');
}

// Extract frontmatter
const parts = content.split('---');
if (parts.length < 3) {
  throw new Error('Invalid frontmatter structure');
}

const frontmatter = parts[1];
const body = parts.slice(2).join('---').trim();

// Basic validation
const requiredFields = ['title', 'slug', 'description', 'author', 'category', 'tags', 'date'];
for (const field of requiredFields) {
  if (!frontmatter.includes(field + ':')) {
    throw new Error(`Missing required frontmatter field: ${field}`);
  }
}

// Extract slug for the filename
const slugMatch = frontmatter.match(/slug:\s*["']?([^"'\n]+)["']?/);
const slug = slugMatch ? slugMatch[1].trim() : $input.first().json.primary_keyword?.replace(/\s+/g, '-').toLowerCase();

if (body.length < 500) {
  throw new Error('Post body too short (< 500 chars). Likely truncated.');
}

return [{
  json: {
    slug,
    filename: `${slug}.md`,
    content: content.trim(),
    valid: true
  }
}];
